<script>
  import { getCombobox } from './combobox.svelte.js'
  import ComboboxOptions from './ComboboxOptions.svelte'
  import { getValueAndLabel, selectOptions } from './select.svelte.js'

  /**
   * @import { Snippet } from 'svelte'
   * @import { SelectEntry } from './select.svelte.js'
   */

  /**
   * @typedef {object} SelectOptionsProps
   * @property {string} id Matches the Select's `target`
   * @property {SelectEntry[]} [items] Options to render. A string is both value and label.
   * @property {HTMLDivElement | null} [ref]
   * @property {string} [class]
   * @property {number} [size] How many options to show before scrolling
   * @property {string} [aria-label]
   * @property {string} [aria-labelledby]
   * @property {Snippet<[any]>} [option] Replaces an option's contents
   * @property {Snippet} [check] Replaces the check a selected option shows
   * @property {Snippet} [children] Options written as `<li>` elements
   */

  /** @type {SelectOptionsProps & Record<string, any>} */
  let { ref = $bindable(null), id, items, option, children, ...rest } = $props()

  // The button part registers it, and it can hydrate after this one
  const multiple = $derived(getCombobox(id)?.options.multiple ?? false)
</script>

<ComboboxOptions
  {...rest}
  {id}
  actions={[{ fn: selectOptions, props: { items } }]}
  inline={false}
  {multiple}
  bind:ref
>
  {#if items}
    {#each items as item, index (index)}
      {@const { value, label } = getValueAndLabel(item)}
      <!-- svelte-ignore a11y_role_has_required_aria_props -->
      <li
        id="{id}-option-{index}"
        data-index={index}
        data-label={label}
        data-value={value}
        role="option"
      >
        {#if option}{@render option(item)}{:else}{label}{/if}
      </li>
    {/each}
  {:else}
    {@render children?.()}
  {/if}
</ComboboxOptions>
